caethyril said:
Rough idea (untested):
Spoiler:
plugin code
JavaScript:
/*:
 * @target MZ
 * @plugindesc Adds a script call to load a game.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/170077/
 * @help In a Script command, you can use this:
 *          loadGame(slotId)
 *     e.g. loadGame(0)   - loads autosave
 *     e.g. loadGame(1)   - loads save ID 1
 * It should load synchronously, blocking updates until complete.
 *
 * Free to use and/or modify for any project, no credit required.
 */
;void (() => {
'use strict';
  let loadId = -1;
  let busy = false;
  globalThis.loadGame = function(slotId) { if (slotId >= 0) loadId = slotId; };
  const load = function() {
    if (loadId >= 0) {
      busy = true;
      DataManager.loadGame(loadId).then(() => {
        SoundManager.playLoad();
        $gamePlayer.reserveTransfer(
          $gameMap.mapId(),
          $gamePlayer.x,
          $gamePlayer.y,
          $gamePlayer.direction(),
          0  // fade black
        );
        if ($gameSystem.versionId() !== $dataSystem.versionId)
          $gamePlayer.requestMapReload();
        SceneManager.goto(Scene_Map);
        $gameSystem.onAfterLoad();
      }).catch(() => {
        SoundManager.playBuzzer();
      }).finally(() => {
        busy = false;
      });
      loadId = -1;
      return true;
    }
    return false;
  };

  // Patch - block scene updates while busy loading.
  void (alias => {
    SceneManager.updateMain = function() {
      if (!busy)
        alias.apply(this, arguments);
      load();
    };
  })(SceneManager.updateMain);

})();
